source("m1.R.fn")
sigs <- function(h) { d <- html_parse(canon(h)); md <- html_markdown(html_parse(h)); back <- html_parse(commonmark::markdown_html(md, extensions=c("table","strikethrough"))); s0 <- sig(d); s1 <- sig(back); t0 <- norm(html_text_clean(d)); t1 <- norm(html_text_clean(back)); cat(sprintf("%s %s\n   md: %s\n   back: %s\n", if (identical(t0,t1)) (if (identical(s0,s1)) "ok  " else "STRUCT") else "TEXT", h, encodeString(md), encodeString(html_serialize(html_element(back,"body"), outer=FALSE)))) }
for (h in c('<p><i><b>A</b>x<b>B</b>y</i></p>', '<p><i><b>bold</b> and <b>bold2</b> end</i></p>', '<p><i><b>a</b>-<b>(b)</b></i></p>', '<p><b><i>A</i>x<i>B</i>y</b></p>', '<p><b><i>a</i> b <i>c</i></b></p>', '<p><i><b>a</b> b <b>c</b></i></p>', '<p><i><b>a</b>, <b>c</b></i></p>','<p><i><b>a</b>,<b>c</b></i></p>', '<p><i>x <b>a</b>,<b>c</b></i></p>', '<p><i><i>a</i></i></p>', '<p><i><em>a</em>b</i></p>', '<p><em><i>a</i> b</em></p>', '<p><b><i>::x</i>=</b><b><i>&amp;</i></b></p>', '<p><b><i>x</i>=</b><b><i>y</i></b></p>', '<p><i>a <b>x</b></i><i>y</i></p>', '<p><i><b>a</b></i><b>c</b></p>', '<p><b>a</b><i><b>c</b></i></p>', '<p><b>a</b><i>b</i><b>c</b></p>', '<p><i>a</i><b>b</b><i>c</i></p>', '<p>x<i>a</i><b>b</b></p>', '<p><b>a<i>b</i></b><i>c</i></p>', '<p><i>a<b>b</b></i><b>c</b></p>', '<p><b>a</b>b<i>c</i>d<b>e</b></p>', '<p><i>a</i>*<i>b</i></p>', '<p><b>a*</b>b</p>', '<p>a<b>*b</b></p>', '<p><i>a</i>_<i>b</i></p>', '<p><i>(a)</i>b</p>', '<p>a<i>(b)</i></p>', '<p><b>a</b>(b)</p>', '<p>"<b>a</b>"<i>b</i></p>', '<p><i>a</i><b>b</b></p>', '<p><b>a</b><i>b</i></p>',
'<ul><li>a<ol><li></li><li>b</li></ol></li></ul>', '<ol><li></li><li>b</li></ol>', '<p>text</p><ol start=2><li>a</ol>', '<ul><li>text<ol start=2><li>a</ol></ul>', '<ol><li>x<ol start=5><li>y</ol></ol>', '<div>text<ol start=3><li>a</ol></div>', 'text<ol start=3><li>a</ol>', '<ul><li><b>t</b><ol start=3><li>a</ol></ul>', '<blockquote>t<ol start=3><li>a</ol></blockquote>', '<ol><li><img src=x><li>b</ol>', '<ul><li>a<ol><li><br></li><li>b</li></ol></li></ul>')) sigs(h)
